62	/** Parse last-seen resource observations without applying the convergence policy. */
63	export function parseDescribeFollow(
64	  text: string,
65	): { readonly resources: readonly DescribeResourceObservation[] } {
66	  const observations = new Map<string, DescribeResourceObservation>();
67	  const lines = text.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
68	  if (lines.length === 0) throw new Error('aspire describe follow stream is empty');
69	  for (const [index, line] of lines.entries()) {
70	    let parsed: unknown;
71	    try {
72	      parsed = JSON.parse(line);
73	    } catch {
74	      throw new Error(`aspire describe follow line ${index + 1} is not JSON`);
75	    }
76	    for (const resource of resources(parsed, index)) observations.set(resource.name, resource);
77	  }
78	  return { resources: [...observations.values()] };
79	}
