81	/** Evaluate last-seen resource state and health from an Aspire describe NDJSON stream. */
82	export function evaluateDescribeFollow(
83	  text: string,
84	  expectedResources: readonly string[],
85	): { readonly resources: readonly DescribeResourceObservation[] } {
86	  const observations = new Map(
87	    parseDescribeFollow(text).resources.map((resource) => [resource.name, resource]),
88	  );
89	  const missing = expectedResources.filter((name) => !observations.has(normalizeName(name)));
90	  if (missing.length > 0) {
91	    throw new Error(`describe stream omitted resources: ${missing.join(', ')}`);
92	  }
93	  const selected = expectedResources.map((name) => observations.get(normalizeName(name))).filter(
94	    (entry): entry is DescribeResourceObservation => entry !== undefined,
95	  );
96	  const pending = selected.filter((entry) => entry.statePending || !isReadyState(entry.state));
97	  if (pending.length > 0) {
98	    throw new Error(
99	      `describe resources did not converge: ${
100	        pending.map((entry) => `${entry.name}=${entry.state}`).join(', ')
101	      }`,
102	    );
103	  }
104	  const unhealthy = selected.flatMap((entry) => [
105	    ...(entry.healthStatus && entry.healthStatus !== 'Healthy'
106	      ? [`${entry.name}.healthStatus=${entry.healthStatus}`]
107	      : []),
108	    ...Object.entries(entry.healthReports)
109	      .filter(([, report]) => report.pending || report.status !== 'Healthy')
110	      .map(([key, report]) => `${entry.name}.healthReports.${key}=${report.status}`),
111	  ]);
112	  if (unhealthy.length > 0) {
113	    throw new Error(`describe resources did not converge: ${unhealthy.join(', ')}`);
114	  }
115	  return { resources: selected };
116	}
