118	/** Assert one resource and optional health report from a captured describe stream. */
119	export function assertDescribeResource(
120	  text: string,
121	  resourceName: string,
122	  healthCheckKey?: string,
123	): DescribeResourceObservation {
124	  const resource = evaluateDescribeFollow(text, [resourceName]).resources[0];
125	  if (!resource) throw new Error(`describe stream omitted ${resourceName}`);
126	  if (healthCheckKey) {
127	    const report = resource.healthReports[healthCheckKey];
128	    if (!report) throw new Error(`${resourceName} omitted healthReports.${healthCheckKey}`);
129	    if (report.status !== 'Healthy') {
130	      throw new Error(
131	        `${resourceName} healthReports.${healthCheckKey} is ${report.status}, expected Healthy`,
132	      );
133	    }
134	  }
135	  return resource;
136	}
