138	/** Start Aspire and capture a bounded describe-follow stream through resource convergence. */
139	export async function captureAspireStartAndDescribe(
140	  appHost: string,
141	  projectRoot: string,
142	  expectedResources: readonly string[],
143	): Promise<void> {
144	  const start = await commandOutput('aspire', [
145	    'start',
146	    '--apphost',
147	    appHost,
148	    '--isolated',
149	    '--non-interactive',
150	    '--nologo',
151	    '--format',
152	    'Json',
153	  ]);
154	  const metadata: unknown = JSON.parse(extractJson(start));
155	  const stateDir = join(projectRoot, '.netscript', 'e2e');
156	  const startPath = join(stateDir, 'aspire-start.json');
157	  const describePath = join(stateDir, 'aspire-describe.ndjson');
158	  await Deno.mkdir(stateDir, { recursive: true });
159	  await Deno.writeTextFile(startPath, `${JSON.stringify(metadata, null, 2)}\n`);
160	  await captureDescribeFollow(appHost, describePath, expectedResources);
161	  console.info(`Aspire describe evidence: ${describePath}`);
162	}
