164	/** Capture a bounded describe-follow stream until the expected resource set converges. */
165	export async function captureDescribeFollow(
166	  appHost: string,
167	  describePath: string,
168	  expectedResources: readonly string[],
169	): Promise<void> {
170	  await Deno.writeTextFile(describePath, '');
171	  const timeoutSeconds = resolveDbCliTimeoutSeconds();
172	  const child = new Deno.Command('aspire', {
173	    args: [
174	      'describe',
175	      '--follow',
176	      '--format',
177	      'Json',
178	      '--apphost',
179	      appHost,
180	      '--non-interactive',
181	      '--nologo',
182	    ],
183	    stdout: 'piped',
184	    stderr: 'piped',
185	  }).spawn();
186	  let timedOut = false;
187	  let converged = false;
188	  let accumulated = '';
189	  const timeout = setTimeout(() => {
190	    timedOut = true;
191	    child.kill('SIGTERM');
192	  }, timeoutSeconds * 1_000);
193	  try {
194	    for await (const line of lines(child.stdout)) {
195	      if (!line.trim()) continue;
196	      accumulated += `${line}\n`;
197	      await Deno.writeTextFile(describePath, `${line}\n`, { append: true });
198	      try {
199	        evaluateDescribeFollow(accumulated, expectedResources);
200	        converged = true;
201	        child.kill('SIGTERM');
202	        break;
203	      } catch (error) {
204	        if (!(error instanceof Error) || !isPendingConvergence(error.message)) throw error;
205	      }
206	    }
207	    const status = await child.status;
208	    if (!converged) {
209	      const stderr = new TextDecoder().decode(await new Response(child.stderr).arrayBuffer())
210	        .trim();
211	      const reason = timedOut
212	        ? `timed out after ${timeoutSeconds}s`
213	        : `exited ${status.code}${stderr ? `: ${stderr}` : ''}`;
214	      throw new Error(`aspire describe --follow did not converge: ${reason}`);
215	    }
216	  } finally {
217	    clearTimeout(timeout);
218	  }
219	}
