221	function resources(value: unknown, lineIndex: number): DescribeResourceObservation[] {
222	  const root = record(value, `describe line ${lineIndex + 1}`);
223	  const wrapped = Reflect.has(root, 'resources');
224	  const source = Reflect.get(root, 'resources');
225	  if (wrapped && !Array.isArray(source)) {
226	    throw new Error(`describe line ${lineIndex + 1} resources is not an array`);
227	  }
228	  const candidates = wrapped && Array.isArray(source) ? source : [root];
229	  return candidates.map((entry, resourceIndex) => resource(entry, lineIndex, resourceIndex));
230	}
231	
232	function resource(
233	  value: unknown,
234	  lineIndex: number,
235	  resourceIndex: number,
236	): DescribeResourceObservation {
237	  const line = describeResourceLine(value, lineIndex, resourceIndex);
238	  const name = describeResourceIdentity(line);
239	  const statePending = line.state === undefined || line.state === null;
240	  return {
241	    name: normalizeName(name),
242	    state: statePending ? 'Unknown' : line.state,
243	    statePending,
244	    ...(line.healthStatus === undefined || line.healthStatus === null
245	      ? {}
246	      : { healthStatus: line.healthStatus }),
247	    healthReports: line.healthReports ?? {},
248	  };
249	}
250	
251	function describeResourceLine(
252	  value: unknown,
253	  lineIndex: number,
254	  resourceIndex: number,
255	): DescribeResourceLine {
256	  const resourceLabel = `describe line ${lineIndex + 1} resource ${resourceIndex + 1}`;
257	  const source = record(value, resourceLabel);
258	  const identity = resourceIdentity(source, resourceLabel);
259	  const fieldLabel = `describe line ${lineIndex + 1} ${identity.value}`;
260	  const state = nullableString(source, 'state', fieldLabel);
261	  const healthStatus = nullableString(source, 'healthStatus', fieldLabel);
262	  const reportsValue = Reflect.get(source, 'healthReports');
263	  const healthReportsValue = reportsValue === undefined
264	    ? undefined
265	    : reportsValue === null
266	    ? null
267	    : healthReports(reportsValue, identity.value, lineIndex);
268	  const nullableFields = {
269	    ...(state === undefined ? {} : { state }),
270	    ...(healthStatus === undefined ? {} : { healthStatus }),
271	    ...(healthReportsValue === undefined ? {} : { healthReports: healthReportsValue }),
272	  };
273	  if (identity.field === 'displayName') {
274	    return { displayName: identity.value, ...nullableFields };
275	  }
276	  if (identity.field === 'name') return { name: identity.value, ...nullableFields };
277	  return { resourceName: identity.value, ...nullableFields };
278	}
279	
280	function resourceIdentity(
281	  source: Record<string, unknown>,
282	  label: string,
283	):
284	  | { readonly field: 'displayName'; readonly value: string }
285	  | { readonly field: 'name'; readonly value: string }
286	  | { readonly field: 'resourceName'; readonly value: string } {
287	  const displayName = nonEmptyString(Reflect.get(source, 'displayName'));
288	  if (displayName) return { field: 'displayName', value: displayName };
289	  const name = nonEmptyString(Reflect.get(source, 'name'));
290	  if (name) return { field: 'name', value: name };
291	  const resourceName = nonEmptyString(Reflect.get(source, 'resourceName'));
292	  if (resourceName) return { field: 'resourceName', value: resourceName };
293	  throw new Error(`${label} omitted identity (displayName/name/resourceName)`);
294	}
295	
296	function describeResourceIdentity(line: DescribeResourceLine): string {
297	  const displayName = nonEmptyString(line.displayName);
298	  if (displayName) return displayName;
299	  const name = nonEmptyString(line.name);
300	  if (name) return name;
301	  const resourceName = nonEmptyString(line.resourceName);
302	  if (resourceName) return resourceName;
303	  throw new Error('DescribeResourceLine identity invariant failed');
304	}
305	
306	function healthReports(
307	  value: unknown,
308	  resourceName: string,
309	  lineIndex: number,
310	): Record<string, DescribeHealthReport> {
311	  const prefix = `describe line ${lineIndex + 1} ${resourceName} healthReports`;
312	  const source = record(value, prefix);
313	  const reports: Record<string, DescribeHealthReport> = {};
314	  for (const [key, candidate] of Object.entries(source)) {
315	    const report = record(candidate, `${prefix}.${key}`);
316	    const status = Reflect.get(report, 'status');
317	    if (status !== undefined && status !== null && typeof status !== 'string') {
318	      throw new Error(`${prefix}.${key} status must be a string, null, or omitted`);
319	    }
320	    const description = Reflect.get(report, 'description');
321	    const details = typeof description === 'string' ? { description } : {};
322	    reports[key] = status === undefined || status === null
323	      ? { status: 'Unknown', pending: true, ...details }
324	      : { status, pending: false, ...details };
325	  }
326	  return reports;
327	}
328	
329	async function* lines(stream: ReadableStream<Uint8Array>): AsyncGenerator<string> {
330	  let buffered = '';
331	  const decoder = new TextDecoder();
332	  for await (const chunk of stream) {
333	    buffered += decoder.decode(chunk, { stream: true });
334	    const parts = buffered.split(/\r?\n/);
335	    buffered = parts.pop() ?? '';
336	    for (const line of parts) yield line;
337	  }
338	  buffered += decoder.decode();
339	  if (buffered) yield buffered;
340	}
341	
342	async function commandOutput(command: string, args: readonly string[]): Promise<string> {
343	  const output = await new Deno.Command(command, {
344	    args: [...args],
345	    stdout: 'piped',
346	    stderr: 'piped',
347	  }).output();
348	  const stdout = new TextDecoder().decode(output.stdout);
349	  const stderr = new TextDecoder().decode(output.stderr).trim();
350	  if (!output.success) throw new Error(`${command} ${args.join(' ')} failed: ${stderr || stdout}`);
351	  return stdout;
352	}
353	
354	function extractJson(output: string): string {
355	  const index = output.indexOf('{');
356	  if (index < 0) throw new Error('aspire start did not emit JSON');
357	  return output.slice(index);
358	}
359	
360	function nullableString(
361	  source: Record<string, unknown>,
362	  key: string,
363	  label: string,
364	): string | null | undefined {
365	  const value = Reflect.get(source, key);
366	  if (value === undefined || value === null || typeof value === 'string') return value;
367	  throw new Error(`${label} ${key} must be a string, null, or omitted`);
368	}
369	
370	function nonEmptyString(value: unknown): string | undefined {
371	  if (typeof value === 'string') {
372	    const trimmed = value.trim();
373	    if (trimmed) return trimmed;
374	  }
375	  return undefined;
376	}
377	
378	function record(value: unknown, label: string): Record<string, unknown> {
379	  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
380	    throw new Error(`${label} is not an object`);
381	  }
382	  return Object.fromEntries(Object.entries(value));
383	}
384	
385	function isReadyState(state: string): boolean {
386	  return READY_STATES.some((candidate) => candidate.toLowerCase() === state.toLowerCase());
387	}
388	
389	function isPendingConvergence(message: string): boolean {
390	  return message.includes('omitted resources:') || message.includes('did not converge:');
391	}
392	
393	function normalizeName(name: string): string {
394	  return name.toLowerCase();
395	}
396	
397	if (import.meta.main) {
398	  const [mode, first, second, third] = Deno.args;
399	  if (mode === 'capture') {
400	    if (!first || !second || !third) {
401	      throw new Error('capture requires AppHost, project root, and expected-resource JSON');
402	    }
403	    const expected: unknown = JSON.parse(third);
404	    if (!Array.isArray(expected) || !expected.every((entry) => typeof entry === 'string')) {
405	      throw new Error('expected-resource JSON must be a string array');
406	    }
407	    await captureAspireStartAndDescribe(first, second, expected);
408	  } else if (mode === 'assert') {
409	    if (!first || !second) throw new Error('assert requires stream path and resource name');
410	    const observation = assertDescribeResource(await Deno.readTextFile(first), second, third);
411	    console.info(`${observation.name} converged at ${observation.state}`);
412	  } else {
413	    throw new Error('mode must be capture or assert');
414	  }
415	}
