import { assertEquals, assertThrows } from '@std/assert';
import {
  assertNoOwnedSurvivors,
  evaluatePostStopProbe,
  pathContained,
  stopCommand,
} from '../../../src/application/gates/scaffold/runtime/evidence/cleanup.ts';

const FIXTURES = new URL('./fixtures/', import.meta.url);

Deno.test('post-stop probe mirrors S7 mount env argv and process-name ownership evidence', async () => {
  const fixture = JSON.parse(
    await Deno.readTextFile(new URL('aspire-post-stop-probe.json', FIXTURES)),
  );
  const result = evaluatePostStopProbe(fixture, fixture.projectRoot);
  assertEquals(result.ownedContainers.map((entry) => entry.id), ['owned-container']);
  assertEquals(result.ownedProcesses.map((entry) => entry.pid), [41, 42]);
  assertEquals(result.foreignContainers.map((entry) => entry.id), ['foreign-container']);
  assertEquals(result.foreignProcesses.map((entry) => entry.pid), [43]);
  assertEquals(result.unprovenContainers.map((entry) => entry.id), [
    'creator-only-container',
    'unproven-container',
  ]);
  assertThrows(
    () => assertNoOwnedSurvivors(result),
    Error,
    'post-stop probe found owned containers: owned-container',
  );
});

Deno.test('post-stop ownership containment is path-boundary safe', () => {
  assertEquals(pathContained('/workspace/app/.data/postgres', '/workspace/app'), true);
  assertEquals(pathContained('/workspace/application/.data/postgres', '/workspace/app'), false);
  assertEquals(pathContained('../app/.data/postgres', '/workspace/app'), false);
});

Deno.test('cleanup adds force only after the exact-apphost graceful stop', () => {
  const appHost = '/workspace/app/aspire/apphost.mts';
  assertEquals(stopCommand(appHost, false), [
    'aspire',
    'stop',
    '--apphost',
    appHost,
    '--non-interactive',
    '--nologo',
  ]);
  assertEquals(stopCommand(appHost, true), [
    'aspire',
    'stop',
    '--force',
    '--apphost',
    appHost,
    '--non-interactive',
    '--nologo',
  ]);
});
import { assertEquals } from '@std/assert';
import { gateArgv } from '../../../../../../.llm/tools/gates/catalog.ts';
import { resourceCommandContract } from '../../../src/application/gates/scaffold/runtime/evidence/resource-command.ts';
import { createResourceCommandGate } from '../../../src/application/gates/scaffold/runtime-gates.ts';
import type { RunContext } from '../../../src/domain/run-context.ts';

Deno.test('resource-command gate owns typed db command background restart describe and skip receipt', () => {
  assertEquals(resourceCommandContract(), {
    id: 'runtime.resource-command',
    typedDatabase: ['resource', '<db>-cli', 'migrate', '--timeout', '60'],
    background: [
      ['resource', 'workers', 'restart'],
      ['resource', 'sagas', 'restart'],
      ['resource', 'triggers', 'restart'],
    ],
    describe: ['describe', '--follow', '--format', 'Json'],
    skipWhenStartReceiptAbsent: true,
  });
  assertEquals(
    gateArgv('cli-e2e-aspire-resource-command').includes(
      '--allow-env=ASPIRE_CLI_START_TIMEOUT',
    ),
    true,
  );
});

Deno.test('resource-command gate registers an explicit absent-start skip receipt', () => {
  const gate = createResourceCommandGate();
  if (gate.kind !== 'command') throw new Error('Expected resource-command command gate.');
  assertEquals(gate.skip, { exitCode: 75, message: 'runtime.aspire-start receipt absent' });
  const context: RunContext = {
    request: {
      suiteId: 'scaffold.runtime',
      options: {
        repoRoot: '/repo',
        cliEntrypoint: 'packages/cli/bin/netscript.ts',
        smokeRoot: '/workspace',
        projectName: 'app',
        database: 'postgres',
        packageSource: 'local',
        plugins: [],
        samples: true,
        cache: true,
        cleanup: true,
        format: 'pretty',
        commandTimeoutMs: 900_000,
        httpTimeoutMs: 30_000,
      },
    },
    project: {
      repoRoot: '/repo',
      cliEntrypoint: 'packages/cli/bin/netscript.ts',
      smokeRoot: '/workspace',
      projectName: 'app',
      projectRoot: '/workspace/app',
      appHost: '/workspace/app/aspire/apphost.mts',
    },
  };
  assertEquals(
    gate.command(context).includes(
      '/repo/.llm/tmp/gate-receipts/scaffold.runtime/runtime.resource-command.json',
    ),
    true,
  );
  assertEquals(gate.command(context).includes('cli-e2e-aspire-resource-command'), true);
  assertEquals(gate.command(context).includes('--allow-env'), true);
  assertEquals(
    gate.command(context).includes(
      '/repo/.llm/tmp/gate-receipts/scaffold.runtime/runtime.resource-command.receipt.json',
    ),
    true,
  );
});

